请对以下 case 进行三维加权评分。

=== case_id ===
Case-19-photo-album-012

=== 用户原始指令 (query.txt) ===
想做一个"重复照片清理提醒"的卡片,有点像待办清单。卡片内嵌几个面板纵向排列,每个面板背景色不一样,黄绿蓝紫交错。每个面板左边放勾选框,右边写重复组信息,比如"8月3日 公园 3张相似"。底部固定一行字"距离相册自动整理还有7天",旁边一个"联系客服"按钮直接拨通电话。哪一组重复超过10张就用红色标"待处理"风险提示。整张卡用夜晚从深紫到靛蓝的渐变,纯文字和色块不要图。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "想做一个\"重复照片清理提醒\"的卡片,有点像待办清单。卡片内嵌几个面板纵向排列,每个面板背景色不一样,黄绿蓝紫交错。每个面板左边放勾选框,右边写重复组信息,比如\"8月3日 公园 3张相似\"。底部固定一行字\"距离相册自动整理还有7天\",旁边一个\"联系客服\"按钮直接拨通电话。哪一组重复超过10张就用红色标\"待处理\"风险提示。整张卡用夜晚从深紫到靛蓝的渐变,纯文字和色块不要图。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToCallPhone",
      "args": {
        "phoneNumber": "950800"
      }
    }
  ],
  "dataModelSchema": {
    "groups": {
      "group0": {
        "checked": {
          "type": "boolean",
          "description": "第一组重复照片是否已勾选",
          "sampleValue": false
        },
        "info": {
          "type": "string",
          "description": "第一组重复照片的日期、地点和相似数量摘要",
          "sampleValue": "8/3 公园 3张相似"
        }
      },
      "group1": {
        "checked": {
          "type": "boolean",
          "description": "第二组重复照片是否已勾选",
          "sampleValue": true
        },
        "info": {
          "type": "string",
          "description": "第二组重复照片的日期、地点和相似数量摘要",
          "sampleValue": "8/5 海边 6张相似"
        }
      },
      "group2": {
        "checked": {
          "type": "boolean",
          "description": "第三组重复照片是否已勾选",
          "sampleValue": false
        },
        "info": {
          "type": "string",
          "description": "第三组重复照片的日期、地点和相似数量摘要",
          "sampleValue": "8/9 聚餐12张"
        },
        "riskLabel": {
          "type": "string",
          "description": "超过10张相似照片时展示的风险提示",
          "sampleValue": "待处理"
        }
      }
    },
    "footer": {
      "reminderText": {
        "type": "string",
        "description": "相册自动整理倒计时提示文案",
        "sampleValue": "自动整理\n还有7天"
      }
    },
    "contact": {
      "actionLabel": {
        "type": "string",
        "description": "联系相册客服的拨号按钮文案",
        "sampleValue": "联系客服"
      }
    }
  },
  "assetCandidates": []
}

